// Reviewed catalog-only adaptation of original AssetVault Add -> spawnObject.
export function attachNativeAssetLibrary({host,signal,onAdd}){
 const doc=host.ownerDocument;let disposed=false,generation=0;
 host.innerHTML='<h2>Current theme object catalog</h2><p>Add an independent instance at the world center, including after the room is empty. Current theme only; no asset downloads, autoplay or cross-theme imports. Adding explicitly adopts existing instance format v6 if needed.</p><p data-asset-library-summary></p><div data-asset-library-list></div><p role="status" data-asset-library-status></p>';
 const list=host.querySelector('[data-asset-library-list]'),summary=host.querySelector('[data-asset-library-summary]'),status=host.querySelector('[data-asset-library-status]');
 function update({key,name,objects,count}){if(disposed)return;const token=++generation;summary.textContent=String(name)+' · '+count+'/100 instances';list.replaceChildren();for(const o of objects){const row=doc.createElement('div'),label=doc.createElement('span'),button=doc.createElement('button');label.textContent=String(o.name)+' · '+String(o.shape)+' · '+String(o.role)+' ';button.textContent='Add '+String(o.name);button.dataset.addCatalogObject=o.id;button.disabled=count>=100;button.addEventListener('click',()=>{if(disposed||token!==generation||!host.contains(button))return;try{const id=onAdd(key,o.id);status.textContent='Added independent instance '+id+'. Undo removes this addition.';}catch(e){status.textContent=String(e.message||'Add failed; no instance created.');}});row.append(label,button);list.append(row);}status.textContent=count>=100?'Instance limit reached. Remove an instance before adding.':'Choose an object to add; existing room content is retained.';}
 function dispose(){if(disposed)return;disposed=true;generation++;signal?.removeEventListener('abort',dispose);host.replaceChildren();}signal?.addEventListener('abort',dispose,{once:true});if(signal?.aborted)dispose();return{update,dispose};
}
